contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit, then attempts withdrawAll; we observe behavior.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for test deposit");

        // record prior observable state: contract balance and this contract's balance
        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;
        // read credit for this test contract before deposit
        uint creditBefore = c.credit(address(this));

        // perform a deposit to set up funds for withdrawal
        c.deposit{value: depositAmount}();

        // after deposit readings
        uint afterDepositCBalance = address(c).balance;
        uint creditAfterDeposit = c.credit(address(this));

        // Now attempt withdrawAll and catch whether it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // readings after withdraw attempt
        uint creditAfter = c.credit(address(this));
        uint afterCBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General rule:
        // If withdrawAll did not revert, then credit for this contract must be zero and
        // the contract's balance must have decreased by at least the amount that credit increased due to our deposit (i.e., creditAfterDeposit - creditBefore).
        // If withdrawAll reverted, credit must be unchanged from afterDeposit state.
        assert(
            (!reverted
                ? (creditAfter == 0 && afterCBalance + (creditAfterDeposit - creditBefore) <= afterDepositCBalance)
                : (creditAfter == creditAfterDeposit))
        );
    }

    // allow receiving ETH from c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read c.credit (it's not public), so we observe effects through balances and behavior.
    // The test deposits amount 'depositAmount' from this contract into c, then attempts withdrawAll.
    // It asserts that if withdrawAll succeeds, then c's balance decreased by depositAmount and
    // this contract's balance increased by depositAmount; if withdrawAll reverts then balances are unchanged.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        // perform deposit to give msg.sender (this contract) credit
        c.deposit{value: depositAmount}();

        // balances after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositMe = address(this).balance;

        // deposit must have transferred depositAmount from this to c
        // (we don't assert that separately; we only use observed values below)

        // try withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // balances after withdraw attempt
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // General rule (single assert):
        // If withdrawAll did not revert, then c.balance decreased by exactly depositAmount
        // (i.e. afterDepositC - afterC == depositAmount) and this contract's balance increased by exactly depositAmount
        // (afterMe - afterDepositMe == depositAmount).
        // If withdrawAll reverted, then balances remained as after the deposit (no change by withdraw attempt).
        assert(
            (!reverted
                ? (afterDepositC >= afterC && afterDepositC - afterC == depositAmount && afterMe >= afterDepositMe && afterMe - afterDepositMe == depositAmount)
                : (afterC == afterDepositC && afterMe == afterDepositMe))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // No precondition needed; ensure no Ether is sent to c in this test function.
        // Read initial observable state
        uint beforeContractBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Ensure caller (this) has zero recorded credit by not depositing anything.
        // Call withdrawAll and capture whether it reverted.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // There is a general rule: if credit was zero then withdrawAll must do nothing and not send Ether.
        // We can observe credit via the public mapping getter credit(address).
        uint creditAfter = c.credit(address(this));

        // Assert: if creditBefore == 0 then creditAfter == 0, balances unchanged, and call did not revert
        // We didn't read creditBefore directly before the call, but since we never deposited, creditBefore == creditAfter == 0.
        // Expressing the general rule: if creditAfter == 0 then balances unchanged and not reverted.
        assert( (creditAfter == 0) ? (afterContractBal == beforeContractBal && afterThisBal == beforeThisBal && reverted == false) : true );
    }

    receive() external payable { }
}

