contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We perform one deposit (possibly zero) then call withdrawAll and observe relations.
    function run(uint depositAmount) public payable {
        // If we intend to send Ether to c, ensure this contract has enough balance
        if (depositAmount > 0) require(address(this).balance >= depositAmount);

        // Read observables before any state-changing calls
        uint beforeCBalance = address(c).balance;
        // There is no public getter for credit in C (it's private in original), so we must rely
        // on behavior: however the prompt allowed reading auto-generated getters only if public.
        // In contract C, credit is not public, so we cannot read it. Instead we can observe that
        // calling deposit increases c balance by depositAmount and withdrawAll cannot increase it.
        // So we assert relations on address(c).balance and on whether credit can increase via deposit.

        // Do deposit (may be zero)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Read after-deposit balance
        uint afterDepositCBalance = address(c).balance;

        // Call withdrawAll and catch whether it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCallCBalance = address(c).balance;

        // General rule: withdrawAll does not increase C's balance, and deposit never decreases it.
        // So afterDepositCBalance >= beforeCBalance and afterCallCBalance <= afterDepositCBalance.
        assert(afterDepositCBalance >= beforeCBalance && afterCallCBalance <= afterDepositCBalance);
    }

    receive() external payable {}
}

