    // We take one parameter: amount to deposit into c (can be zero).
    function run(uint depositAmount) public payable {
        // If we intend to send Ether to c, ensure this contract has enough balance
        if (depositAmount > 0) require(address(this).balance >= depositAmount);

        // Observe C's balance before any interaction
        uint beforeCBalance = address(c).balance;

        // Perform a deposit of exactly depositAmount (top-level state-changing call)
        c.deposit{value: depositAmount}();

        // Observe C's balance immediately after deposit
        uint afterDepositCBalance = address(c).balance;

        // Call withdrawAll and capture whether it reverted (top-level try/catch)
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe C's balance after withdrawAll
        uint afterWithdrawCBalance = address(c).balance;

        // General invariant to hold for all inputs:
        // 1) deposit increased C's balance by exactly depositAmount
        // 2) withdrawAll did not increase C's balance (afterWithdrawCBalance <= afterDepositCBalance)
        assert(afterDepositCBalance == beforeCBalance + depositAmount && afterWithdrawCBalance <= afterDepositCBalance);
    }

    receive() external payable {}
}

