contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    function run(address other) public payable {
        // precondition: we will act as the caller (this contract). `other` is unused but required as a parameter.
        require(other != address(0) || true);

        // ensure we haven't deposited: we observe credit via the public getter credit(address)
        uint beforeCredit = c.credit(address(this));
        // require that beforeCredit is zero to test the rule case; if it's not zero the assert below will be vacuously false
        // but we avoid reverting here so the checker can try different inputs/state — hence we only proceed.

        // perform the call under test and catch reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable values after the call
        uint afterCredit = c.credit(address(this));
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        // General rule: if credit was zero before, withdrawAll must not revert, must leave C's balance and caller credit unchanged (credit stays zero).
        assert(!(beforeCredit == 0) || (reverted == false && afterCredit == 0 && cBalanceAfter == address(c).balance && beforeCredit == afterCredit));
    }

    // receive to accept ETH if needed by other tests
    receive() external payable {}
}
